-- Run with BEGIN / ROLLBACK; fixtures never create real orders, money or messages.
do $$
declare uid uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid(); t uuid; other_area uuid;
 task uuid:=gen_random_uuid(); request_id uuid:=gen_random_uuid(); r jsonb; n integer; checks integer:=0;
begin
 select id into t from public.tambons order by created_at limit 1;
 select id into other_area from public.tambons where id<>t order by created_at limit 1;
 insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values(uid,'d55-'||uid||'@qa.invalid','{}','{}');
 insert into public.profiles(id,full_name,role,approved,is_test) values(uid,'QA D55','customer',true,true);
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,uid,now(),now());
 insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method) values(gen_random_uuid(),sid,now(),now(),'password');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 if public.agent_dashboard_access(t) then raise exception 'unappointed access'; end if; checks:=checks+1;
 insert into public.admin_scopes(profile_id,tambon_id) values(uid,t);
 if not public.agent_dashboard_access(t) or public.agent_dashboard_access(other_area) then raise exception 'area guard'; end if; checks:=checks+1;
 if jsonb_array_length(public.agent_dashboard_areas())<>1 then raise exception 'areas scope'; end if; checks:=checks+1;
 begin perform public.agent_dashboard(other_area); raise exception 'cross area read allowed'; exception when insufficient_privilege then null; end; checks:=checks+1;
 begin perform public.agent_work_save(other_area,gen_random_uuid(),'QA task','','orders'); raise exception 'cross area write allowed'; exception when insufficient_privilege then null; end; checks:=checks+1;
 r:=public.agent_work_save(t,task,'QA task','local-only QA detail','orders');
 perform public.agent_work_save(t,task,'QA task','local-only QA detail','orders');
 if (select count(*) from public.agent_work_items where id=task)<>1 or (select count(*) from public.agent_work_events where task_id=task)<>1 then raise exception 'create duplicate'; end if; checks:=checks+1;
 begin perform public.agent_work_save(t,task,'different title','local-only QA detail','orders'); raise exception 'retry changed input'; exception when invalid_parameter_value then null; end; checks:=checks+1;
 r:=public.agent_work_update(task,request_id,1,'start','QA progress');
 perform public.agent_work_update(task,request_id,1,'start','QA progress');
 if (select version from public.agent_work_items where id=task)<>2 or (select count(*) from public.agent_work_events where task_id=task)<>2 then raise exception 'update duplicate'; end if; checks:=checks+1;
 begin perform public.agent_work_update(task,gen_random_uuid(),1,'done',''); raise exception 'stale overwrite'; exception when serialization_failure then null; end; checks:=checks+1;
 begin perform public.agent_work_update(task,gen_random_uuid(),null,'done',''); raise exception 'null version bypass'; exception when serialization_failure then null; end; checks:=checks+1;
 begin perform public.agent_work_update(task,gen_random_uuid(),2,'wait',''); raise exception 'waiting without reason'; exception when invalid_parameter_value then null; end; checks:=checks+1;
 r:=public.agent_memory_snapshot(t);
 if r::text like '%local-only%' or r::text like '%QA task%' or r->'summary'->'counts' ? 'payout_amount' then raise exception 'private memory fields'; end if; checks:=checks+1;
 if r->>'revision' is distinct from public.agent_memory_snapshot(t)->>'revision' then raise exception 'unstable revision'; end if; checks:=checks+1;
 perform public.agent_work_update(task,gen_random_uuid(),2,'done','QA done');
 if public.agent_dashboard(t)->'task_counts'->>'done'='0' then raise exception 'projection not updated'; end if; checks:=checks+1;
 update public.profiles set suspended_at=now() where id=uid;
 if public.agent_dashboard_access(t) then raise exception 'suspended access'; end if; checks:=checks+1;
 update public.profiles set suspended_at=null where id=uid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true);
 if public.agent_dashboard_access(t) then raise exception 'unknown auth method allowed'; end if; checks:=checks+1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true);
 execute 'set local role authenticated';
 select count(*) into n from public.agent_work_items where tambon_id=other_area;
 if n<>0 then raise exception 'RLS cross area'; end if;
 select count(*) into n from public.agent_work_items where id=task;
 if n<>1 then raise exception 'RLS own area missing'; end if; checks:=checks+1;
 begin update public.agent_work_items set status='done' where id=task; raise exception 'direct update allowed'; exception when insufficient_privilege then null; end; checks:=checks+1;
 execute 'reset role';
 if has_function_privilege('anon','public.agent_dashboard(uuid,text,integer)','EXECUTE') or has_function_privilege('anon','public.agent_work_save(uuid,uuid,text,text,text,date,bigint)','EXECUTE') then raise exception 'anon execute'; end if; checks:=checks+1;
 raise notice 'D55 rollback checks passed: %',checks;
end;
$$;
